function onBarcodeMetalTypeChange() {
    var metalSelectEl = document.getElementById('barcodeMetalType');
    if (!metalSelectEl) return;
    var prev = currentBarcodeMetalKey;
    if (prev) {
        barcodeSettingsByMetal[prev] = captureMetalSettingsSnapshot();
    }
    var newMetal = metalSelectEl.value || '';
    currentBarcodeMetalKey = newMetal;
    try { if (newMetal) sessionStorage.setItem('barcode_setting_metal', newMetal); } catch (e) {}
    activateToolboxCategory(metalDisplayToToolboxCategory(newMetal));
    if (newMetal === '') {
        applyMetalSettingsSnapshot(null);
        return;
    }
    if (barcodeSettingsByMetal[newMetal]) {
        applyMetalSettingsSnapshot(barcodeSettingsByMetal[newMetal]);
        return;
    }
    fetch('ajax/get-barcode-settings.php?metal_type=' + encodeURIComponent(newMetal), { credentials: 'same-origin' })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            if (data.success && data.settings) {
                barcodeSettingsByMetal[newMetal] = data.settings;
                applyMetalSettingsSnapshot(data.settings);
            } else {
                applyMetalSettingsSnapshot(null);
            }
        })
        .catch(function() { applyMetalSettingsSnapshot(null); });
}

